//! Routes a bundle from the first to the last ground station of the `rrs_s80_g05` LEO
//! Ring Road (80 cubesats with ISLs, 5 ground stations), generated by
//! `benches/leo_scenarios/generate.sh`, and prints the route found by:
//! - SABR (Dijkstra) with no node management,
//! - A* with the delay heuristic,
//! - A* with the bucket heuristic.
//!
//! The scenario has no `"distances"` matrix and all its contact delays are 0, so the delay
//! heuristic is 0 everywhere and A* behaves like Dijkstra.

use std::{fs::File, io::BufReader};

use a_sabr::{
    bundle::Bundle,
    contact_manager::segmentation::seg::SegmentationManager,
    contact_plan::{ContactPlan, from_tvgutil_file::TVGUtilContactPlan},
    distance::sabr::SABR,
    errors::ASABRError,
    multigraph::{Multigraph, NodeRef},
    node_manager::{
        bucket_heuristic::BucketHeuristicManager, delay_heuristic::DelayHeuristicManager,
        none::NoManagement,
    },
    pathfinding::{AStarNodeParenting, NodeParenting, Pathfinding},
    types::Date,
    utils::make_guard,
};
use serde_json::Value;

type CM = SegmentationManager;
type DelayNM = DelayHeuristicManager<NoManagement>;
type BucketNM = BucketHeuristicManager<NoManagement>;

const SCENARIO: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/benches/leo_scenarios/rrs_s80_g05.json"
);
const SOURCE: &str = "gs0";
const DEST: &str = "gs4";
const N_BUCKETS: usize = 256;

const BUNDLE: Bundle = Bundle {
    priority: 0,
    size: 1_000,
    expiration: Date::MAX,
};

/// Finds a route from `$source` to `$dest` at `$time` on `$plan` with `$finder`, and prints
/// it hop by hop, naming the nodes with `$names`.
macro_rules! print_route {
    ($label:expr, $plan:expr, $finder:ty, $names:expr, $source:expr, $dest:expr, $time:expr) => {{
        make_guard!(id);
        let mut graph = Multigraph::new(id, $plan)?;
        let source =
            graph
                .node_id_ref($source.into())?
                .internal()
                .ok_or(ASABRError::ContactPlanError(
                    "source is not an internal node",
                ))?;
        let mut dest = graph.node_id_ref($dest.into())?.routable()?;

        let mut finder = <$finder>::new();
        let output = finder.find_path(&mut graph, $time, source, &BUNDLE, &mut dest, None)?;

        println!("{}:", $label);
        match output.as_ref().and_then(|o| o.full_path_rev(dest, &graph)) {
            None => println!("    no route found"),
            Some(path) => {
                let mut hops: Vec<_> = path.collect();
                hops.reverse();
                for frag in hops {
                    let node = usize::from(graph.into_nodeid(NodeRef::from(frag.rx_node)));
                    println!(
                        "    {:>2} hop(s)  {:<16} t={} (+{} s)",
                        frag.hop_count,
                        $names[node],
                        frag.recv.end,
                        frag.recv.end - $time,
                    );
                }
            }
        }
        println!();
    }};
}

fn main() -> Result<(), ASABRError> {
    let json: Value = serde_json::from_reader(BufReader::new(
        File::open(SCENARIO).expect("run benches/leo_scenarios/generate.sh first"),
    ))
    .expect("invalid JSON");

    // the parser numbers the nodes in the order of the "vertices" object
    let names: Vec<String> = json["vertices"]
        .as_object()
        .ok_or(ASABRError::ContactPlanError("no \"vertices\" in json"))?
        .keys()
        .cloned()
        .collect();
    let id = |name: &str| {
        names
            .iter()
            .position(|n| n == name)
            .ok_or(ASABRError::ContactPlanError("node not found"))
    };
    let (source, dest) = (id(SOURCE)?, id(DEST)?);

    let plan: ContactPlan<NoManagement, CM> = TVGUtilContactPlan::parse(json.clone())?;
    let delay_plan: ContactPlan<DelayNM, CM> = TVGUtilContactPlan::parse(json)?;
    let bucket_plan = BucketNM::wrap_plan(plan.clone(), N_BUCKETS);

    // route at the first contact of the plan
    let time = plan
        .contacts
        .iter()
        .map(|(c, _, _)| c.lifespan.start)
        .min()
        .ok_or(ASABRError::ContactPlanError("empty contact plan"))?;

    println!("{SCENARIO}");
    println!("{SOURCE} -> {DEST}, starting at t={time}\n");

    print_route!(
        "SABR, no management",
        plan,
        NodeParenting<SABR>,
        names,
        source,
        dest,
        time
    );
    print_route!(
        "A* with delay heuristic",
        delay_plan,
        AStarNodeParenting<SABR>,
        names,
        source,
        dest,
        time
    );
    print_route!(
        format!("A* with bucket heuristic ({N_BUCKETS} buckets)"),
        bucket_plan,
        AStarNodeParenting<SABR>,
        names,
        source,
        dest,
        time
    );

    Ok(())
}
